<body>

<canvas id="scene" tabindex="0" data-i18n-aria="canvasAria" aria-label="Mô hình 3D các cây cầu trên sông Hàn, Đà Nẵng"></canvas>
<div id="loading"><span data-i18n="loading">Đang dựng các cây cầu Đà Nẵng…</span><small data-i18n="loadingSub">Cầu Rồng, Thuận Phước, Trần Thị Lý, cầu quay sông Hàn và hầm vượt sông Hàn</small></div>

<header class="panel brand">
  <div class="brand-top">
    <div class="eyebrow" data-i18n="eyebrow">Sông Hàn · 16,061°N · 108,227°E</div>
    <label class="lang"><span hidden data-i18n="language">Ngôn ngữ</span><select id="langSelect" data-i18n-aria="language" aria-label="Ngôn ngữ"></select></label>
  </div>
  <div class="brand-head">
    <h1><span data-i18n="h1" class="h1-main">Đà Nẵng</span></h1>
    <button id="btnSettings" aria-expanded="false" aria-controls="brandBody" data-i18n-aria="settings" aria-label="Cài đặt">
      <svg viewBox="0 0 16 16" aria-hidden="true"><path fill="currentColor" fill-rule="evenodd" d="M6.9 1h2.2l.4 1.9 1.2.5 1.6-1.1 1.6 1.6-1.1 1.6.5 1.2 1.9.4v2.2l-1.9.4-.5 1.2 1.1 1.6-1.6 1.6-1.6-1.1-1.2.5-.4 1.9H6.9l-.4-1.9-1.2-.5-1.6 1.1-1.6-1.6 1.1-1.6-.5-1.2L.8 9.1V6.9l1.9-.4.5-1.2-1.1-1.6 1.6-1.6 1.6 1.1 1.2-.5zM8 5.6a2.4 2.4 0 1 0 0 4.8 2.4 2.4 0 0 0 0-4.8z"/></svg>
    </button>
    <button class="sheet-close" data-i18n-aria="close" aria-label="Đóng"><svg viewBox="0 0 16 16" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" d="M3.5 3.5l9 9m0-9l-9 9"/></svg></button>
  </div>
  <div id="brandBody">
  <div class="row">
    <button id="btnNight" aria-pressed="false">Chuyển sang đêm</button>
    <button id="btnShadow" aria-pressed="true" data-i18n="shadows">Bóng đổ</button>
  </div>
  <div class="audio-row">
    <button id="btnMusic" aria-pressed="false">
      <svg class="note" viewBox="0 0 16 16" aria-hidden="true"><path fill="currentColor" d="M6 2.5v8.1A2.5 2.5 0 1 0 7.5 13V6l6-1.5v4.6A2.5 2.5 0 1 0 15 11.5V1z"/></svg>
      <svg class="eq" viewBox="0 0 16 16" aria-hidden="true"><rect x="2" y="3" width="3" height="11" rx="1" fill="currentColor"/><rect x="6.5" y="3" width="3" height="11" rx="1" fill="currentColor"/><rect x="11" y="3" width="3" height="11" rx="1" fill="currentColor"/></svg>
      <span data-i18n="music">Nhạc nền</span>
    </button>
    <button id="btnVoice" aria-pressed="true" disabled>
      <svg viewBox="0 0 16 16" aria-hidden="true"><path fill="currentColor" d="M8 1a2.5 2.5 0 0 0-2.5 2.5v4a2.5 2.5 0 0 0 5 0v-4A2.5 2.5 0 0 0 8 1zM3 7a.75.75 0 0 1 1.5 0 3.5 3.5 0 0 0 7 0A.75.75 0 0 1 13 7a5 5 0 0 1-4.25 4.94V14.5h1.5a.75.75 0 0 1 0 1.5h-4.5a.75.75 0 0 1 0-1.5h1.5v-2.56A5 5 0 0 1 3 7z"/></svg>
      <span data-i18n="voice">Thuyết minh</span>
    </button>
    <input id="volSlider" type="range" min="0" max="100" value="70" data-i18n-aria="volume" aria-label="Âm lượng" disabled>
  </div>
  <label class="slider" for="timeSlider"><span data-i18n="day">Ngày</span> <input id="timeSlider" type="range" min="0" max="100" value="0"> <span data-i18n="night">Đêm</span></label>
  <div class="weather-row">
    <label class="mini-select" for="weatherSel"><span data-i18n="weather">Thời tiết</span>
      <select id="weatherSel"><option value="now" data-i18n="wxNow" selected>Hiện trạng</option><option value="summer" data-i18n="wxSummer">Nắng hè</option><option value="rain" data-i18n="wxRain">Mưa</option><option value="monsoon" data-i18n="wxMonsoon">Gió mùa</option><option value="storm" data-i18n="wxStorm">Bão</option></select></label>
    <label class="slider" for="weatherK"><span data-i18n="wxIntensity">Cường độ</span> <input id="weatherK" type="range" min="0" max="100" value="100"> <span id="weatherKVal">100%</span></label>
    <button id="btnWxImpact" class="toggle" aria-pressed="false" aria-controls="wxImpact" data-i18n="wxImpact">Ảnh hưởng tới cầu</button>
    <div id="wxImpact" class="wx-impact" hidden aria-live="off"></div>
    <button id="btnWxStorm" class="toggle" aria-pressed="false">Kịch bản bão</button>
  </div>
  <label class="mini-select" for="qualitySel"><span data-i18n="quality">Chất lượng hình</span>
    <select id="qualitySel"><option value="auto" selected>Tự động</option><option value="high" data-i18n="qHigh">Cao</option><option value="medium" data-i18n="qMed">Trung bình</option><option value="low" data-i18n="qLow">Thấp</option></select></label>
  <a id="donateLink" class="donate" target="_blank" rel="noopener noreferrer" data-i18n-aria="donateAria" aria-label="Mời tác giả một ly cà phê qua MoMo (mở tab mới)" hidden>
    <svg viewBox="0 0 16 16" aria-hidden="true"><path fill="currentColor" d="M3 6h8v4.8A2.2 2.2 0 0 1 8.8 13H5.2A2.2 2.2 0 0 1 3 10.8V6zm8.5 1H12a1.5 1.5 0 0 1 0 3h-1V8h1a.5.5 0 0 0 0-1h-.5zM2 14h11v1H2z"/><path fill="none" stroke="currentColor" stroke-linecap="round" stroke-width="1.2" d="M5 4c.8-.8 0-1.3 0-2m3 2c.8-.8 0-1.3 0-2"/></svg>
    <span>Buy me a coffee</span>
  </a>
  </div>
</header>

<nav class="panel views" data-i18n-aria="views" aria-label="Góc nhìn">
  <div class="label" data-i18n="views">Góc nhìn</div>
  <div class="seg" role="group">
    <button data-bridge="dragon" aria-pressed="true" data-i18n="bridgeDragon">Cầu Rồng</button>
    <button data-bridge="tp" aria-pressed="false" data-i18n="bridgeTp">Cầu Thuận Phước</button>
    <button data-bridge="ttl" aria-pressed="false" data-i18n="bridgeTtl">Cầu Trần Thị Lý</button>
    <button data-bridge="sh" aria-pressed="false" data-i18n="bridgeSh">Cầu sông Hàn</button>
    <button data-bridge="hr" aria-pressed="false" data-i18n="bridgeHr">Hầm sông Hàn</button>
    <button data-bridge="sw" aria-pressed="false" data-i18n="bridgeSw">Vòng quay Mặt Trời</button>
  </div>
  <button class="tour-all" data-view="allTour" aria-pressed="false" data-i18n="vTourAll">Tour 4 cầu</button>
  <button id="btnViewsSheet" aria-expanded="false">
    <svg viewBox="0 0 16 16" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" d="M2.5 4h11M2.5 8h11M2.5 12h11"/></svg>
    <span data-i18n="views">Góc nhìn</span>
  </button>
  <button class="sheet-close" data-i18n-aria="close" aria-label="Đóng"><svg viewBox="0 0 16 16" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" d="M3.5 3.5l9 9m0-9l-9 9"/></svg></button>
  <div class="view-list" data-list="dragon">
  <button data-view="tour" aria-pressed="false" data-i18n="vTour">Tour tự động</button>
  <button data-view="overview" aria-pressed="true" data-i18n="vOverview">Toàn cảnh trên cao</button>

